insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_66_v1'
from (values
('127.414.d.1',3,'A flight-test engineer sees data showing a wing fitting is overstressed but the test program is behind schedule. The ethical choice is to:','["report the data and recommend a fix", "wait until the next test", "delete the data point", "skip the report"]'::jsonb,0,'Safety data must be reported honestly.','original'),
('127.414.d.1',4,'A licensed engineer is asked to seal drawings for an airframe design outside her field of expertise. The ethical response is to:','["seal it anyway", "decline until a qualified engineer reviews it", "guess at the calculations", "let an intern sign"]'::jsonb,1,'Engineers practice only within their competence.','original'),
('127.414.d.2.A',3,'An aerospace team lists the stages of its design process on a wall chart so everyone can see the current:','["weather forecast", "team playlist", "stage of the project", "lunch menu"]'::jsonb,2,'Process stages organize work.','original'),
('127.414.d.2.A',4,'Implementing the stages of a design process for a small drone means documenting the problem, concepts, test results, and:','["jokes", "rumors", "menus", "design revisions"]'::jsonb,3,'Documentation shows how the design evolved.','original'),
('127.414.d.2.B',3,'A drone project with a short deadline and a small budget is limited mainly by its:','["scope and resources", "name", "color", "slogan"]'::jsonb,0,'Scope and resources bound what is possible.','original'),
('127.414.d.2.B',4,'An ethical factor in choosing a drone''s camera design is protecting the:','["weight of the box", "privacy of people on the ground", "brand of batteries", "color of the housing"]'::jsonb,1,'Ethics affects design decisions.','original'),
('127.414.d.2.C',3,'For an airport-security drone, the neighbors near the runway are stakeholders because they are affected by its:','["paint", "color", "noise and flight paths", "price of parts"]'::jsonb,2,'Stakeholders include those affected by the design.','original'),
('127.414.d.2.C',4,'A design team that consults the aviation regulator early is considering a stakeholder whose approval is:','["unrelated", "cosmetic", "optional", "required to operate the aircraft"]'::jsonb,3,'Regulators control approval.','original'),
('127.414.d.2.D',3,'A wing-tip test that cracks at a lower load than predicted is valuable because it exposes a:','["weakness before real flight", "extra cost only", "reason to quit", "new color"]'::jsonb,0,'Failure in test prevents failure in service.','original'),
('127.414.d.2.D',4,'Test pilots and engineers study accident investigations to turn past failures into:','["delay", "design and procedure improvements", "blame", "secrecy"]'::jsonb,1,'Failure analysis improves safety.','original'),
('127.414.d.3.A',3,'A phase of project management that follows planning and comes before closing is:','["retirement", "approval", "execution", "amnesia"]'::jsonb,2,'Work is carried out during execution.','original'),
('127.414.d.3.A',4,'In a stage-gate process for a new airframe, a gate review decides whether the project can:','["be renamed", "be painted", "be forgotten", "move on to the next stage"]'::jsonb,3,'Gates control progression.','original'),
('127.414.d.3.B',3,'On an aircraft design team, the chief engineer is responsible for the overall:','["technical direction of the design", "paint color", "parking", "lunch orders"]'::jsonb,0,'Chief engineers guide technical decisions.','original'),
('127.414.d.3.B',4,'A subsystem lead for avionics reports progress on her subsystem to the:','["vendor only", "project manager", "press only", "competitor"]'::jsonb,1,'Leads communicate status upward.','original'),
('127.414.d.3.C',3,'Project software that shows tasks as bars on a timeline is a:','["map", "music player", "Gantt chart tool", "recipe app"]'::jsonb,2,'Gantt tools display schedules.','original'),
('127.414.d.3.C',4,'When choosing between Agile and stage-gate tools for a hardware-heavy aircraft program, a team should consider how well each handles:','["photo filters", "music playback", "games", "formal reviews and physical build milestones"]'::jsonb,3,'Tools should fit the work.','original'),
('127.414.d.3.D',3,'A change log that records who revised a drawing and when helps the team to:','["track document history", "delete drawings", "guess dates", "hide changes"]'::jsonb,0,'Revision history prevents confusion.','original'),
('127.414.d.3.D',4,'A configuration control system ensures that technicians build from the:','["verbal notes only", "current approved drawings", "a rumor", "oldest sketch"]'::jsonb,1,'Controlled documents prevent mistakes.','original'),
('127.414.d.3.E',3,'A requirement that an aircraft climb to 3,000 m within 10 minutes is both a requirement and a measurable:','["color", "guess", "performance target", "opinion"]'::jsonb,2,'Targets are verified by testing.','original'),
('127.414.d.3.E',4,'A late customer request to double payload capacity will most likely force changes to the project''s:','["lunch plan", "office decor", "logo only", "schedule, budget, and design"]'::jsonb,3,'Requirement changes affect everything.','original'),
('127.414.d.3.F',3,'An aircraft program budget includes labor, test equipment, and:','["materials and flight-test costs", "rumors", "vacations", "trophies"]'::jsonb,0,'Costs include testing.','original'),
('127.414.d.3.F',4,'If wind-tunnel time costs 2,000 dollars per day and the plan needs 5 days, the wind-tunnel budget line is:','["400 dollars", "10,000 dollars", "7,000 dollars", "2,005 dollars"]'::jsonb,1,'2,000 x 5 = 10,000.','original'),
('127.414.d.3.G',3,'Management of change requires that a proposed modification to a flight-critical part be:','["made first and checked later", "made by anyone", "reviewed and approved before it is made", "kept secret"]'::jsonb,2,'MOC prevents untracked changes.','original'),
('127.414.d.3.G',4,'A change from aluminum to titanium for a bracket should go through MOC because it affects weight, cost, and:','["team size", "paint name", "meeting time", "structural performance"]'::jsonb,3,'Changes have ripple effects.','original'),
('127.414.d.4.A',3,'Sensemaking helps a team assign the person who is best at stress analysis to the:','["structures tasks", "marketing", "catering", "parking"]'::jsonb,0,'Match skills to tasks.','original'),
('127.414.d.4.A',4,'A team that notices a member is overloaded and shifts work to others is practicing:','["conflict", "sensemaking within the team", "avoidance", "delay"]'::jsonb,1,'Awareness balances workload.','original'),
('127.414.d.4.B',3,'A Gantt chart helps a team see which tasks can run at the same time and which are:','["colored", "optional", "dependent on others", "hidden"]'::jsonb,2,'Dependencies show on the chart.','original'),
('127.414.d.4.B',4,'In an Agile team, a short daily meeting where members share progress and blockers is a:','["sleep-in", "sit-down dinner", "walk-out", "stand-up"]'::jsonb,3,'Stand-ups keep everyone aligned.','original'),
('127.414.d.4.C',3,'When critiquing a teammate''s flight-control diagram, the ''analyzing'' step asks:','["how the parts relate to each other", "who drew it", "what color is it", "how long it took"]'::jsonb,0,'Analysis examines relationships.','original'),
('127.414.d.4.C',4,'The ''evaluating'' step of critique judges the diagram against the:','["author''s mood", "stated requirements", "paper size", "font choice"]'::jsonb,1,'Evaluation uses criteria.','original'),
('127.414.d.4.D',3,'A team that agrees to hold weekly status meetings and rotate note-taking has developed an:','["accident", "delay", "action plan to support teamwork", "excuse"]'::jsonb,2,'Plans formalize teamwork.','original'),
('127.414.d.4.D',4,'To make a team action plan effective, each step should have an owner and a:','["slogan", "password", "nickname", "target date"]'::jsonb,3,'Ownership and dates drive follow-through.','original'),
('127.414.d.4.E',3,'A helpful way to critique a teammate''s report is to point to a specific section and explain how to:','["improve it", "insult it", "erase it", "ignore it"]'::jsonb,0,'Specific advice is useful.','original'),
('127.414.d.4.E',4,'Modeling effective critique for newer team members means demonstrating feedback that is:','["vague and harsh", "specific, respectful, and tied to goals", "sarcastic", "rare"]'::jsonb,1,'Good examples teach good habits.','original'),
('127.414.d.4.F',3,'When another team''s landing-gear design appears to violate a requirement, a respectful critique would:','["call the design bad", "laugh", "cite the requirement and the part in question", "stay silent"]'::jsonb,2,'Evidence-based feedback is respectful.','original'),
('127.414.d.4.F',4,'Giving feedback to another team across a table works best when the comments are:','["off topic", "rushed", "personal", "clear and about the work product"]'::jsonb,3,'Focus on the product.','original'),
('127.414.d.4.G',3,'A team gets ten critique comments and decides which ones to act on by comparing each with the:','["project requirements and goals", "author''s mood", "weather", "day of the week"]'::jsonb,0,'Evaluate comments against goals.','original'),
('127.414.d.4.G',4,'If a critique comment is unclear, the team should:','["assume the worst", "ask the reviewer to clarify", "delete the comment", "ignore everything"]'::jsonb,1,'Clarify before acting.','original'),
('127.414.d.4.H',3,'A design review presentation for a propulsion subsystem should show the current design, risks, and:','["lunch plans", "jokes", "open questions for reviewers", "secret data"]'::jsonb,2,'Reviews seek input.','original'),
('127.414.d.4.H',4,'A good design review slide uses a clear figure and brief text so reviewers can quickly see the:','["cover art", "slide background", "author''s photo", "key decision to be reviewed"]'::jsonb,3,'Clarity helps reviewers.','original'),
('127.414.d.5.A',3,'A reverse engineering form for a small turbine records the parts, materials, and:','["how they are assembled", "shipping color", "owner''s name", "purchase price"]'::jsonb,0,'Forms capture disassembly details.','original'),
('127.414.d.5.A',4,'An executive summary for a flight-test report should state the objective, the main result, and the:','["team mascot", "recommendation", "parking rule", "lunch menu"]'::jsonb,1,'Summaries give the key takeaways.','original'),
('127.414.d.5.B',3,'The best format for showing a mission profile of altitude over time is a:','["poem", "paragraph", "graph", "contract"]'::jsonb,2,'Graphs show trends.','original'),
('127.414.d.5.B',4,'The best format for listing component masses and totals is a:','["photo", "story", "cartoon", "table"]'::jsonb,3,'Tables organize numbers.','original'),
('127.414.d.5.C',3,'A report on a wind-tunnel test should present the setup before the:','["results", "title", "index", "cover"]'::jsonb,0,'Setup comes before results.','original'),
('127.414.d.5.C',4,'Sequencing a report from requirements to design to test helps the reader see how the design:','["smells", "satisfies the requirements", "costs", "looks"]'::jsonb,1,'Structure supports the argument.','original'),
('127.414.d.5.D',3,'Written steps for assembling a model rocket should be tested by a person who has not:','["seen a rocket", "read a manual", "built it before", "used a tool"]'::jsonb,2,'A fresh reader finds gaps.','original'),
('127.414.d.5.D',4,'A user manual for a drone should include safety warnings before the steps that involve:','["decorating", "unpacking", "naming", "spinning propellers"]'::jsonb,3,'Hazards must be flagged before the task.','original'),
('127.414.d.5.E',3,'The final design report for an aircraft concept should state the mission it was designed for and whether the design:','["meets the mission requirements", "is famous", "is pretty", "is cheap to ship"]'::jsonb,0,'Reports show results against goals.','original'),
('127.414.d.5.E',4,'Including a lessons-learned section in a final report helps future teams to:','["skip planning", "avoid repeating mistakes", "ignore results", "copy errors"]'::jsonb,1,'Lessons carry forward.','original'),
('127.414.d.6.A',3,'A mission requires an aircraft to carry 500 kg of payload to an altitude of 5,000 m. These are examples of:','["team names", "paint choices", "mission requirements", "budget lines only"]'::jsonb,2,'Altitude and payload define the mission.','original'),
('127.414.d.6.A',4,'Given mission requirements for speed, altitude, and payload, the first design step is to:','["name the aircraft", "choose a paint color", "order materials", "analyze what each requirement demands of the aircraft"]'::jsonb,3,'Analysis comes before concepts.','original'),
('127.414.d.6.B',3,'A sub-requirement derived from a range requirement might be a minimum:','["fuel capacity", "paint thickness", "logo size", "seat count"]'::jsonb,0,'Range drives fuel capacity.','original'),
('127.414.d.6.B',4,'A requirement to cruise at 200 km/h at 3,000 m might generate a sub-requirement for the engine to deliver adequate:','["paint adhesion", "thrust or power at altitude", "cabin music", "seat comfort"]'::jsonb,1,'Performance needs propulsion.','original'),
('127.414.d.6.C',3,'Sketching several different aircraft layouts that could meet the same mission is called generating:','["final drawings", "invoices", "conceptual solutions", "contracts"]'::jsonb,2,'Concepts are early layouts.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_66_v1'
from (values
('127.414.d.6.C',4,'A team documents each conceptual aircraft with a sketch, a description, and how it addresses the:','["weather", "lunch menu", "team mascot", "mission requirements"]'::jsonb,3,'Documentation links concepts to needs.','original'),
('127.414.d.6.D',3,'Grouping concepts as fixed-wing, rotorcraft, or lighter-than-air is a way of:','["classifying conceptual solutions", "naming", "painting", "coloring"]'::jsonb,0,'Classification organizes options.','original'),
('127.414.d.6.D',4,'Classifying concepts into categories helps a team to compare:','["colors", "similar options against each other", "unrelated things", "salaries"]'::jsonb,1,'Categories make comparisons fair.','original'),
('127.414.d.6.E',3,'Selecting a conceptual solution requires the team to justify the choice using:','["personal preference only", "a coin toss", "evidence from the analysis", "volume of votes"]'::jsonb,2,'Justification uses data.','original'),
('127.414.d.6.E',4,'The record of why a concept was chosen over others is important because it lets reviewers:','["avoid the review", "skip testing", "hide the choice", "understand and check the decision"]'::jsonb,3,'Documented rationale supports review.','original'),
('127.414.d.6.F',3,'A matrix that shows how each requirement is addressed by each design feature models the:','["relationships between requirements and the design", "schedule only", "weather", "payroll"]'::jsonb,0,'Matrices reveal coverage.','original'),
('127.414.d.6.F',4,'A graph of range versus payload for a concept helps the team see the:','["length of the manual", "trade-off between payload and range", "price of paint", "number of seats"]'::jsonb,1,'Trade-off curves show limits.','original'),
('127.414.d.7.A',3,'A project plan that includes time, deliverables, and cost estimates helps the team to:','["avoid planning", "guess dates", "track progress against the plan", "hide costs"]'::jsonb,2,'Plans enable tracking.','original'),
('127.414.d.7.A',4,'A cost estimate in a project plan should be updated when the team learns that a part will cost more than:','["nothing", "zero", "it did before", "originally expected"]'::jsonb,3,'Estimates change with knowledge.','original'),
('127.414.d.7.B',3,'In a stage-gate process, formal review checkpoints that decide whether to proceed are called:','["gates", "party", "lunch", "holiday"]'::jsonb,0,'Gates are formal review points.','original'),
('127.414.d.7.B',4,'If a gate review finds a stage incomplete, the team should:','["skip ahead", "finish the work before moving on", "ignore the findings", "close the project"]'::jsonb,1,'Gates ensure readiness.','original'),
('127.414.d.7.C',3,'A test plan for a prototype wing states the loads to apply, the measurements to record, and the:','["lunch plan", "weather report", "pass or fail criteria", "team nickname"]'::jsonb,2,'Criteria define success.','original'),
('127.414.d.7.C',4,'Executing a documented test plan means following the steps exactly and recording the:','["rumors", "opinions only", "excuses", "results"]'::jsonb,3,'Records support conclusions.','original'),
('127.414.d.7.D',3,'Periodic design reviews give the team a chance to explain and defend its:','["design choices", "lunch order", "vacation plans", "dress code"]'::jsonb,0,'Reviews test the reasoning.','original'),
('127.414.d.7.D',4,'A review that surfaces a conflict with a requirement early is valuable because the fix is usually:','["impossible", "cheaper than later", "unnecessary", "more expensive"]'::jsonb,1,'Early fixes cost less.','original'),
('127.414.d.7.E',3,'A final design report has an executive summary, a body with details, and:','["jokes", "a blank page", "appendices with supporting data", "a menu"]'::jsonb,2,'Appendices hold supporting detail.','original'),
('127.414.d.7.E',4,'The body of a final design report should be organized so a reader can follow the design from the requirements to the:','["team photos", "lunch", "weather", "verification results"]'::jsonb,3,'Order tells the design story.','original'),
('127.414.d.8.A',3,'A design parameter derived from a lift requirement is the wing''s:','["area", "name", "color", "price"]'::jsonb,0,'Wing area affects lift.','original'),
('127.414.d.8.A',4,'Design parameters such as wingspan, wing area, and engine thrust come from the mission and the:','["paint", "sub-requirements", "weather", "logo"]'::jsonb,1,'Parameters follow from requirements.','original'),
('127.414.d.8.B',3,'Generating several wing shapes, each with different aspect ratios, is documenting:','["reports", "final products", "design concepts for a parameter", "budgets"]'::jsonb,2,'Concepts address parameters.','original'),
('127.414.d.8.B',4,'A concept sheet should record the idea, a sketch, and how it addresses the:','["mascot", "weather", "lunch", "design parameter"]'::jsonb,3,'Documentation links ideas to needs.','original'),
('127.414.d.8.C',3,'A decision matrix scoring three wing concepts on lift, weight, and cost helps the team to:','["narrow the concepts", "avoid analysis", "skip testing", "pick randomly"]'::jsonb,0,'Matrices prune choices.','original'),
('127.414.d.8.C',4,'A pro-con list is a quick way to prune a concept set when the options are few and the criteria are:','["meaningless", "easy to describe", "secret", "unlimited"]'::jsonb,1,'Pro-cons suit simple comparisons.','original'),
('127.414.d.8.D',3,'Building a small model of a candidate wing to test in a wind tunnel is creating a:','["contract", "logo", "prototype for testing", "sales brochure"]'::jsonb,2,'Prototypes validate concepts.','original'),
('127.414.d.8.D',4,'After a prototype test, the team compares the results to its predictions to decide how to:','["avoid testing", "hide data", "celebrate only", "modify the concept"]'::jsonb,3,'Results guide modifications.','original'),
('127.414.d.8.E',3,'A pair-wise comparison used late in design helps the team to rank the remaining:','["prototype designs", "team members", "parking spots", "menu items"]'::jsonb,0,'Ranking narrows options.','original'),
('127.414.d.8.E',4,'After the tools rank two prototypes closely, the team should combine the matrix results with:','["personal taste only", "test data and engineering judgment", "a coin flip", "popularity"]'::jsonb,1,'Tools inform judgment.','original'),
('127.414.d.8.F',3,'Evaluating a prototype means identifying where it falls short of the:','["mascot", "decorations", "requirements", "budget for lunch"]'::jsonb,2,'Evaluation compares to requirements.','original'),
('127.414.d.8.F',4,'A prototype that meets lift but exceeds the weight limit shows an area for:','["celebration only", "stopping", "hiding results", "improvement in the next iteration"]'::jsonb,3,'Iteration addresses gaps.','original'),
('127.414.d.8.G',3,'After revising a prototype, the team tests it again to see whether the modification:','["improved performance", "changed the color", "changed the title", "raised the cost only"]'::jsonb,0,'Retesting confirms improvement.','original'),
('127.414.d.8.G',4,'Documenting the revised prototype''s performance relative to the mission requirements shows whether it:','["is pretty", "meets the mission", "is cheap", "is large"]'::jsonb,1,'Documentation closes the loop.','original'),
('127.414.d.8.H',3,'A project debrief presentation includes what was done, what worked, and the:','["paint colors", "next vacation", "lessons learned", "team''s lunch"]'::jsonb,2,'Debriefs capture lessons.','original'),
('127.414.d.8.H',4,'Sharing lessons learned at the end of a project helps the organization to:','["delay work", "repeat errors", "hide problems", "improve future projects"]'::jsonb,3,'Lessons improve future work.','original'),
('127.414.d.9.A',3,'Pilots control rotation about the longitudinal axis, called roll, using the:','["ailerons", "elevator", "rudder", "trim wheel only"]'::jsonb,0,'Ailerons roll the aircraft.','original'),
('127.414.d.9.A',4,'A rudder pedal input mainly changes the aircraft''s motion about the:','["lateral axis", "vertical axis", "horizontal ground plane", "longitudinal axis"]'::jsonb,1,'The rudder controls yaw.','original'),
('127.414.d.9.B',3,'An aircraft in steady flight has thrust 8,000 N and drag 5,000 N. The net force forward is:','["5,000 N", "13,000 N", "3,000 N", "8,000 N"]'::jsonb,2,'8,000 - 5,000 = 3,000.','original'),
('127.414.d.9.B',4,'With net forward force of 3,000 N on an aircraft of mass 1,500 kg, the acceleration is:','["3,000 m/s2", "4.5 m/s2", "0.5 m/s2", "2 m/s2"]'::jsonb,3,'a = F / m = 3,000 / 1,500 = 2.','original'),
('127.414.d.9.C',3,'The load on an aircraft''s wings is greater in a steep banked turn than in level flight because the wings must produce:','["more lift", "less lift", "no lift", "only drag"]'::jsonb,0,'Turn load factor increases lift required.','original'),
('127.414.d.9.C',4,'Wing loads during landing flare and gusts can exceed normal cruise loads, so designers include:','["fewer ribs", "a safety margin in structural design", "no margin", "extra paint"]'::jsonb,1,'Margins protect against unusual loads.','original'),
('127.414.d.9.D',3,'In straight and level flight, an aircraft that weighs 20 kilonewtons needs lift equal to:','["200 N", "40,000 N", "20,000 N", "10,000 N"]'::jsonb,2,'Lift balances weight.','original'),
('127.414.d.9.D',4,'A level turn with a load factor of 2 requires lift of how much for a 20,000 N aircraft?','["22,000 N", "10,000 N", "20,000 N", "40,000 N"]'::jsonb,3,'2 x 20,000 = 40,000.','original'),
('127.414.d.9.E',3,'The horizontal stabilizer and elevator provide stability and control about the:','["pitch axis", "vertical axis only", "yaw axis", "roll axis"]'::jsonb,0,'The tail surfaces handle pitch.','original'),
('127.414.d.9.E',4,'The vertical fin provides stability to resist unwanted:','["pitching", "yawing motion", "climbing", "rolling only"]'::jsonb,1,'The fin keeps the nose pointed into the wind.','original'),
('127.414.d.10.A',3,'The lift equation shows that lift is proportional to the wing area and the square of the:','["color", "altitude only", "airspeed", "pilot weight"]'::jsonb,2,'L = 1/2 x rho x V^2 x S x CL.','original'),
('127.414.d.10.A',4,'If airspeed doubles and all else stays the same, lift becomes:','["half as large", "unchanged", "two times larger", "four times larger"]'::jsonb,3,'Lift varies with the square of speed.','original'),
('127.414.d.10.B',3,'The drag equation shows that drag is proportional to air density, wing area, the drag coefficient, and the square of:','["velocity", "pilot''s weight", "color", "cabin pressure"]'::jsonb,0,'D = 1/2 x rho x V^2 x S x CD.','original'),
('127.414.d.10.B',4,'If the drag coefficient is reduced by 50 percent and all else stays the same, the drag becomes:','["unchanged", "half as large", "quadrupled", "doubled"]'::jsonb,1,'Drag is proportional to CD.','original'),
('127.414.d.10.C',3,'At higher altitude where air density is lower, lift at the same airspeed and angle of attack is:','["unchanged", "infinite", "less", "greater"]'::jsonb,2,'Lift depends on density.','original'),
('127.414.d.10.C',4,'Air density at 5,000 m is about half that of sea level. At the same speed and angle, lift will be about:','["twice as large", "unchanged", "four times as large", "half as large"]'::jsonb,3,'Lift is proportional to density.','original'),
('127.414.d.10.D',3,'Trailing-edge flaps increase lift at low speed by increasing the wing''s:','["camber and area", "weight only", "thickness only", "color"]'::jsonb,0,'Flaps change the airfoil shape.','original'),
('127.414.d.10.D',4,'Leading-edge slats help delay stall by allowing the wing to fly at a higher:','["weight", "angle of attack", "altitude only", "speed only"]'::jsonb,1,'Slats keep flow attached.','original'),
('127.414.d.10.E',3,'Spoilers on top of a wing are used to reduce lift and increase:','["altitude", "thrust", "drag", "weight"]'::jsonb,2,'Spoilers dump lift and add drag.','original'),
('127.414.d.10.E',4,'Deploying spoilers after touchdown helps a landing aircraft to:','["climb", "stall", "take off again", "stay on the runway and slow down"]'::jsonb,3,'Reducing lift improves braking.','original'),
('127.414.d.10.F',3,'Extending flaps lowers the stall speed because the wing can produce the needed lift at a:','["lower airspeed", "greater weight", "higher altitude", "higher airspeed"]'::jsonb,0,'Flaps increase maximum lift.','original'),
('127.414.d.10.F',4,'A heavier aircraft has a higher stall speed because it needs more:','["fuel color", "lift to stay airborne", "drag", "paint"]'::jsonb,1,'Stall speed rises with weight.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
