insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_66_v1'
from (values
('127.415.d.5.J',3,'A line from the center of a circle to its edge is a:','["radius", "chord", "diameter", "tangent"]'::jsonb,0,'The radius is center to edge.','original'),
('127.415.d.5.J',4,'A line that touches a circle at exactly one point is a:','["diameter", "tangent", "chord", "radius"]'::jsonb,1,'A tangent touches once.','original'),
('127.415.d.5.K',3,'A circle has a radius of 5 m. Its diameter is:','["2.5 m", "5 m", "10 m", "25 m"]'::jsonb,2,'Diameter = 2r.','original'),
('127.415.d.5.K',4,'A circular water tank has a radius of 2 m. Using pi = 3.14, its circumference is about:','["25.12 m", "6.28 m", "4 m", "12.56 m"]'::jsonb,3,'2 x 3.14 x 2 = 12.56.','original'),
('127.415.d.5.L',3,'A line with equation y = 2x + 1 has a slope of:','["2", "0.5", "3", "1"]'::jsonb,0,'Slope is the coefficient of x.','original'),
('127.415.d.5.L',4,'On the line y = 2x + 1, when x = 3, y equals:','["6", "7", "5", "9"]'::jsonb,1,'2 x 3 + 1 = 7.','original'),
('127.415.d.5.M',3,'The volume of a cylinder is pi times the radius squared times the:','["area", "diameter", "height", "circumference"]'::jsonb,2,'V = pi r^2 h.','original'),
('127.415.d.5.M',4,'A rectangular concrete slab is 10 m long, 5 m wide, and 0.2 m thick. Its volume is:','["50 cubic meters", "15.2 cubic meters", "1 cubic meter", "10 cubic meters"]'::jsonb,3,'10 x 5 x 0.2 = 10.','original'),
('127.415.d.6.A',3,'The U.S. survey foot is slightly different from the:','["international foot", "mile marker", "inch only", "meter stick only"]'::jsonb,0,'The two feet differ by a tiny amount.','original'),
('127.415.d.6.A',4,'Surveyors measuring a long boundary in Texas need to know which foot a plan uses because the difference grows over:','["time of day", "long distances", "short distances", "no distance"]'::jsonb,1,'Small differences add up.','original'),
('127.415.d.6.B',3,'An angle measured up or down from the horizontal is a:','["horizontal angle only", "compass bearing", "vertical angle", "right angle only"]'::jsonb,2,'Vertical angles measure elevation change.','original'),
('127.415.d.6.B',4,'One full turn around a point is how many degrees?','["90", "180", "100", "360"]'::jsonb,3,'A circle is 360 degrees.','original'),
('127.415.d.6.C',3,'A cubic yard is a common unit used to order:','["concrete", "wire", "ink", "lumber lengths only"]'::jsonb,0,'Concrete is ordered by volume.','original'),
('127.415.d.6.C',4,'A trench 3 ft wide, 3 ft deep, and 9 ft long has a volume of how many cubic feet?','["27", "81", "15", "9"]'::jsonb,1,'3 x 3 x 9 = 81.','original'),
('127.415.d.6.D',3,'An acre is a unit of:','["length", "temperature", "area", "volume"]'::jsonb,2,'Acres measure land area.','original'),
('127.415.d.6.D',4,'A rectangular lot measures 200 ft by 100 ft. Its area in square feet is:','["200,000", "300", "2,000", "20,000"]'::jsonb,3,'200 x 100 = 20,000.','original'),
('127.415.d.6.E',3,'To convert feet to miles, divide by the number of feet in one mile, which is:','["5,280", "1,000 feet", "12 feet", "100 feet"]'::jsonb,0,'1 mile = 5,280 ft.','original'),
('127.415.d.6.E',4,'A site is 43,560 square feet. Since one acre is 43,560 square feet, the site is:','["2 acres", "1 acre", "0.5 acre", "10 acres"]'::jsonb,1,'43,560 / 43,560 = 1.','original'),
('127.415.d.6.F',3,'Differential leveling finds the change in elevation between points using a level and a:','["scale", "compass", "rod", "clock"]'::jsonb,2,'Rod readings give height differences.','original'),
('127.415.d.6.F',4,'A level rod reads 5.2 ft on the backsight and 3.7 ft on the foresight. The elevation changes by:','["8.9 ft", "5.2 ft", "3.7 ft", "1.5 ft"]'::jsonb,3,'5.2 - 3.7 = 1.5.','original'),
('127.415.d.6.G',3,'A surveyor may measure the distance between two points using a steel tape, a total station, or:','["GPS", "a magnifying glass", "a calendar", "a thermometer"]'::jsonb,0,'Different methods suit different jobs.','original'),
('127.415.d.6.G',4,'Pacing is a quick but low-accuracy way to measure distance compared with a:','["guess", "total station", "stopwatch", "step count"]'::jsonb,1,'Instruments are more accurate.','original'),
('127.415.d.6.H',3,'Two methods measure the same distance as 100.00 m and 100.02 m. The two results disagree by:','["2 m", "100 m", "two centimeters", "0.2 m"]'::jsonb,2,'100.02 - 100.00 = 0.02.','original'),
('127.415.d.6.H',4,'Comparing errors from two methods helps a surveyor choose the method that gives the better:','["speed only", "color", "weight", "accuracy for the job"]'::jsonb,3,'Error comparison guides method choice.','original'),
('127.415.d.6.I',3,'Failing to level an instrument correctly introduces a:','["systematic error", "design", "perfect reading", "random only"]'::jsonb,0,'Setup mistakes create consistent errors.','original'),
('127.415.d.6.I',4,'Analyzing survey data for blunders, such as a misread rod, involves looking for values that are:','["identical", "far from the rest", "close to the mean", "negative only"]'::jsonb,1,'Outliers may indicate mistakes.','original'),
('127.415.d.7.A',3,'The Roman aqueducts are historic civil engineering works that carried:','["cars", "trains", "water", "planes"]'::jsonb,2,'Aqueducts moved water to cities.','original'),
('127.415.d.7.A',4,'The development of the arch was significant to historic bridges because arches carry loads in:','["spin", "tension", "torsion", "compression"]'::jsonb,3,'Stone arches rely on compression.','original'),
('127.415.d.7.B',3,'The Galveston Seawall, built after the 1900 hurricane, was built to protect the city from:','["storm surge", "earthquakes", "landslides", "volcanoes"]'::jsonb,0,'The seawall resists storm waves.','original'),
('127.415.d.7.B',4,'Major Texas water projects such as dams on the Colorado River have supported flood control, water supply, and:','["mining", "power generation", "train service", "air travel"]'::jsonb,1,'Dams serve multiple purposes.','original'),
('127.415.d.7.C',3,'The Hoover Dam is a major U.S. civil engineering project built to control the:','["Hudson River", "Missouri River", "Colorado River", "Ohio River"]'::jsonb,2,'Hoover Dam is on the Colorado River.','original'),
('127.415.d.7.C',4,'The interstate highway system changed U.S. travel and trade by providing connected, high-speed:','["waterways only", "rails only", "airports only", "roads"]'::jsonb,3,'It connected the country by road.','original'),
('127.415.d.8.A',3,'A civil project begins with conception, followed by scope definition, proposal, and:','["contracting", "retiring", "forgetting", "hiding"]'::jsonb,0,'Phases follow a sequence.','original'),
('127.415.d.8.A',4,'Writing the scope of a project defines what work is included and what is:','["painted", "excluded", "named", "colored"]'::jsonb,1,'Scope sets boundaries.','original'),
('127.415.d.8.B',3,'In a project life cycle, construction comes after design and before:','["scoping", "proposal", "closeout", "conception"]'::jsonb,2,'Closeout ends the project.','original'),
('127.415.d.8.B',4,'Four project phases are planning, construction, operation, and the idea stage. The idea stage that comes first is called:','["operation", "construction", "closeout only", "conception"]'::jsonb,3,'Conception comes first.','original'),
('127.415.d.9.A',3,'A feasibility study for a new bridge would examine technical, financial, and:','["environmental factors", "music factors", "sports factors", "fashion factors"]'::jsonb,0,'Feasibility has several dimensions.','original'),
('127.415.d.9.A',4,'A feasibility study is important because it helps decide whether a project should:','["be forgotten only", "proceed", "be named", "be painted"]'::jsonb,1,'It informs go or no-go decisions.','original'),
('127.415.d.9.B',3,'The costs of a new park might include land, construction, and:','["profit", "rumor", "maintenance", "vacation"]'::jsonb,2,'Costs continue after construction.','original'),
('127.415.d.9.B',4,'A benefit of a new park that is hard to put a price on is improved community:','["noise", "traffic jams", "debt", "well-being"]'::jsonb,3,'Some benefits are intangible.','original'),
('127.415.d.9.C',3,'A project costs 2 million dollars and provides 3 million dollars in benefits. The benefit-cost ratio is:','["1.5", "6", "5", "0.67"]'::jsonb,0,'3 / 2 = 1.5.','original'),
('127.415.d.9.C',4,'A benefit-cost ratio greater than 1 means the project''s benefits are:','["equal to zero", "greater than its costs", "unknown", "less than its costs"]'::jsonb,1,'Ratio above 1 favors the project.','original'),
('127.415.d.9.D',3,'A common risk on a construction project is a delay caused by bad:','["paint", "music", "weather", "lunch"]'::jsonb,2,'Weather causes delays.','original'),
('127.415.d.9.D',4,'A risk that the soil at the site is weaker than expected would be a:','["fashion risk", "music risk", "marketing risk", "geotechnical risk"]'::jsonb,3,'Soil conditions are a classic risk.','original'),
('127.415.d.9.E',3,'Risk analysis that multiplies the chance of an event by its impact is a:','["probability and impact assessment", "weather report", "lunch order", "color chart"]'::jsonb,0,'Risk = probability x impact.','original'),
('127.415.d.9.E',4,'A risk with a high chance and a high impact should be given:','["low priority", "high priority for mitigation", "a nickname", "no attention"]'::jsonb,1,'Big risks come first.','original'),
('127.415.d.9.F',3,'A feasibility report for a small project includes the project description, analysis, and a:','["joke", "menu", "recommendation", "rumor"]'::jsonb,2,'Reports end with a recommendation.','original'),
('127.415.d.9.F',4,'A recommendation in a feasibility report should be supported by the:','["cover design", "author''s mood", "font", "analysis"]'::jsonb,3,'Evidence supports conclusions.','original'),
('127.415.d.9.G',3,'An RFQ is a request for:','["qualifications", "quotas", "quartz", "quarterly reports"]'::jsonb,0,'RFQs ask firms for their qualifications.','original'),
('127.415.d.9.G',4,'Agencies issue an RFQ to help choose a firm based on its experience and:','["name", "capability", "color", "location only"]'::jsonb,1,'RFQs focus on qualification.','original'),
('127.415.d.9.H',3,'When evaluating RFQ responses, a team compares each firm''s experience to the project''s:','["name", "logo", "scope", "color"]'::jsonb,2,'Fit to scope is key.','original'),
('127.415.d.9.H',4,'A firm with strong bridge experience would score best on an RFQ for a:','["parade", "bakery", "music festival", "bridge design project"]'::jsonb,3,'Experience should match the project.','original'),
('127.415.d.9.I',3,'Building codes and environmental regulations are examples of rules that affect:','["civil engineering design", "fashion", "music tastes", "sports scores"]'::jsonb,0,'Codes constrain designs.','original'),
('127.415.d.9.I',4,'A project near a wetland must follow regulations that protect:','["fashion", "water and habitat", "parking", "signage only"]'::jsonb,1,'Environmental rules apply.','original'),
('127.415.d.9.J',3,'A scope of work document describes the tasks, deliverables, and:','["jokes", "rumors", "schedule", "menus"]'::jsonb,2,'Scopes list work and timing.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_66_v1'
from (values
('127.415.d.9.J',4,'A clear scope of work helps prevent disputes between the client and the:','["weather", "moon", "tourists", "contractor"]'::jsonb,3,'Clarity prevents disagreements.','original'),
('127.415.d.9.K',3,'A scope of work for a small drainage project would list the work to be done, the products to be delivered, and the:','["time allowed", "author''s age", "font", "color of paper"]'::jsonb,0,'Timelines are part of the scope.','original'),
('127.415.d.9.K',4,'Writing the exclusions in a scope document tells everyone what work is:','["included", "not included", "optional only", "secret"]'::jsonb,1,'Exclusions prevent misunderstandings.','original'),
('127.415.d.10.A',3,'A conceptual schematic for a new road might be a sketch showing the route and:','["mascots", "colors only", "major features", "jokes"]'::jsonb,2,'Schematics show the basic layout.','original'),
('127.415.d.10.A',4,'A simple diagram showing how stormwater flows from a roof to a detention pond is a conceptual:','["contract", "budget", "permit", "schematic diagram"]'::jsonb,3,'Schematics show relationships.','original'),
('127.415.d.10.B',3,'A conceptual sketch for a parking lot should show entrances, parking areas, and:','["drainage direction", "paint color", "menu", "music"]'::jsonb,0,'Sketches convey key design ideas.','original'),
('127.415.d.10.B',4,'A concept drawing is meant to communicate the design idea to:','["competitors only", "the client and design team", "no one", "pets"]'::jsonb,1,'Concepts are communication tools.','original'),
('127.415.d.10.C',3,'Calculating the required pipe diameter for a storm drain is an example of a common civil engineering:','["poem", "menu", "design calculation", "joke"]'::jsonb,2,'Design calcs size components.','original'),
('127.415.d.10.C',4,'A beam sizing calculation verifies that the beam can resist the expected:','["colors", "names", "prices", "loads"]'::jsonb,3,'Calculations confirm capacity.','original'),
('127.415.d.10.D',3,'Reviewing plans for conflicts, such as a pipe passing through a beam, is a:','["quality control check", "lunch", "painting", "joke"]'::jsonb,0,'QC finds errors before construction.','original'),
('127.415.d.10.D',4,'Checking that the drawings match the written specifications helps ensure the plans and specs are:','["random", "consistent", "contradictory", "hidden"]'::jsonb,1,'Consistency prevents disputes.','original'),
('127.415.d.10.E',3,'A quantity take-off lists the amount of each material needed, such as cubic yards of concrete and feet of:','["music", "sports", "pipe", "paint colors"]'::jsonb,2,'Take-offs measure quantities.','original'),
('127.415.d.10.E',4,'An estimate of probable construction cost multiplies each quantity by its:','["weight only", "color", "age", "unit price"]'::jsonb,3,'Cost = quantity x unit price.','original'),
('127.415.d.11.A',3,'A total station, a level, and GPS receivers are tools used by civil engineers and surveyors to:','["measure and layout sites", "bake bread", "paint walls", "play music"]'::jsonb,0,'These tools measure positions.','original'),
('127.415.d.11.A',4,'A drone with a camera is used on construction sites to take:','["tax forms", "aerial photos and measurements", "phone calls only", "lunch orders"]'::jsonb,1,'Drones provide aerial data.','original'),
('127.415.d.11.B',3,'Hand drafting on paper was largely replaced in civil engineering by:','["knitting", "typewriters", "computer-aided drafting", "chalkboards"]'::jsonb,2,'CAD increased speed and accuracy.','original'),
('127.415.d.11.B',4,'Technology such as GPS and drones has made surveying faster and more:','["expensive only", "difficult", "confusing", "efficient"]'::jsonb,3,'New tools improve work.','original'),
('127.415.d.11.C',3,'Design analysis software helps engineers predict how a structure will respond to:','["loads", "colors", "names", "prices"]'::jsonb,0,'Analysis predicts behavior.','original'),
('127.415.d.11.C',4,'Computer-aided drafting software lets engineers create precise plan sheets that can be easily:','["erased forever", "revised and shared", "lost", "hidden"]'::jsonb,1,'CAD improves editing and sharing.','original'),
('127.415.d.12.A',3,'A final inspection on a construction project may involve the owner, the engineer, the contractor, and the:','["tourist", "neighbor''s dog", "building inspector", "competitor"]'::jsonb,2,'Inspections involve several parties.','original'),
('127.415.d.12.A',4,'A final inspection checks that the work matches the plans and meets applicable:','["rumors", "moods", "menus", "codes"]'::jsonb,3,'Codes must be satisfied.','original'),
('127.415.d.12.B',3,'A punch list is a list of items that still need to be:','["completed or corrected", "celebrated", "deleted", "painted blue"]'::jsonb,0,'Punch lists track remaining work.','original'),
('127.415.d.12.B',4,'Organizing a punch list by trade helps assign each item to the right:','["vendor of lunch", "subcontractor", "customer", "pet"]'::jsonb,1,'Trade grouping simplifies assignment.','original'),
('127.415.d.12.C',3,'Evaluating a completed project to find what worked and what did not helps the team to:','["blame others", "repeat errors", "learn for the next project", "hide issues"]'::jsonb,2,'Post-project reviews build knowledge.','original'),
('127.415.d.12.C',4,'A project closeout review often compares the final cost and schedule to the:','["song list", "wish list", "rumors", "original plan"]'::jsonb,3,'Comparison reveals variance.','original'),
('127.415.d.13.A',3,'A construction document set typically includes a plat, site plans, and:','["construction specifications", "stories", "menus", "music"]'::jsonb,0,'Sets include drawings and specs.','original'),
('127.415.d.13.B',3,'A fire protection plan shows hydrants, sprinklers, and how a building is protected from and responds to a:','["floods only", "blaze", "sunshine", "music"]'::jsonb,1,'It lays out fire safety measures.','original'),
('127.415.d.13.A',4,'A plat is a map that shows how land is divided into:','["colors", "plants only", "lots and streets", "songs"]'::jsonb,2,'Plats show subdivisions.','original'),
('127.415.d.13.B',4,'A fire protection plan may show fire hydrants, sprinkler layouts, and:','["paint colors", "furniture", "picture frames", "emergency access routes"]'::jsonb,3,'Plans include response access.','original'),
('127.415.d.13.C',3,'A paving plan shows pavement sections, which describe the layers of material under a:','["road surface", "carpet", "wall", "roof"]'::jsonb,0,'Pavement sections list layers.','original'),
('127.415.d.13.C',4,'A typical pavement section includes a subgrade, a base course, and a:','["wall course", "surface course", "roof course", "water course"]'::jsonb,1,'Layers support traffic loads.','original'),
('127.415.d.13.D',3,'Construction specifications are written documents that describe the required:','["parking", "lunch menus", "materials and workmanship", "color of paper"]'::jsonb,2,'Specs complement drawings.','original'),
('127.415.d.13.D',4,'If a drawing and a specification conflict, the team should first:','["ignore both", "pick the cheaper one", "guess", "ask the engineer for clarification"]'::jsonb,3,'Resolve conflicts through the engineer.','original'),
('127.415.d.13.E',3,'A title block on a drawing shows the project name, sheet number, and:','["date and engineer information", "recipes", "lunch", "jokes"]'::jsonb,0,'Title blocks identify the sheet.','original'),
('127.415.d.13.E',4,'A legend on a drawing explains the meaning of the:','["author''s age", "symbols used", "sheet size", "weather"]'::jsonb,1,'Legends define symbols.','original'),
('127.415.d.13.F',3,'Drafting a plan to scale means every length on the drawing is a consistent fraction of the:','["lunch time", "paper size", "real length", "pencil width"]'::jsonb,2,'Scale keeps proportions.','original'),
('127.415.d.13.F',4,'At a scale of 1 inch = 20 feet, a 3-inch line on the drawing represents how many feet?','["17 feet", "23 feet", "6.7 feet", "60 feet"]'::jsonb,3,'3 x 20 = 60.','original'),
('127.415.d.13.G',3,'To fit a large site on a small sheet, an engineer chooses a scale with a:','["larger ratio", "random ratio", "smaller ratio", "zero ratio"]'::jsonb,0,'A smaller drawing needs a larger ratio.','original'),
('127.415.d.13.G',4,'A 200-foot-wide site is drawn at a scale of 1 inch = 20 feet. On the sheet, its width measures:','["2 inches", "10 inches", "20 inches", "200 inches"]'::jsonb,1,'200 / 20 = 10.','original'),
('127.415.d.13.H',3,'Specifications and drawings must agree so that the contractor builds:','["nothing", "a surprise", "what the engineer designed", "something different"]'::jsonb,2,'Documents must be coordinated.','original'),
('127.415.d.13.H',4,'If the drawings show a pipe size and the specification gives a different size, the conflict can cause:','["perfect results", "fast approval", "good weather", "cost and schedule problems"]'::jsonb,3,'Conflicts cause rework.','original'),
('127.415.d.13.I',3,'Design drawings show what the engineer intended, while record drawings show what was actually:','["built", "priced", "imagined", "proposed"]'::jsonb,0,'Record drawings document as-built conditions.','original'),
('127.415.d.13.I',4,'Record drawings are valuable to the owner after construction because they show the:','["staff lunches", "as-built locations of utilities", "colors", "original sketches"]'::jsonb,1,'They help with future maintenance.','original'),
('127.415.d.14.A',3,'A systematic organizational structure for project documents helps team members find files:','["randomly", "slowly", "quickly", "never"]'::jsonb,2,'Structure saves time.','original'),
('127.415.d.14.A',4,'Storing drawings, specs, and correspondence in separate labeled folders is an example of a:','["menu", "timetable", "budget", "document organization system"]'::jsonb,3,'Folders organize files.','original'),
('127.415.d.14.B',3,'A project file structure usually has folders by discipline, such as civil, structural, and:','["electrical", "games", "fashion", "music"]'::jsonb,0,'Disciplines organize drawings.','original'),
('127.415.d.14.B',4,'Developing a file structure at the start of a project helps prevent files from becoming:','["accurate", "disorganized", "labeled", "complete"]'::jsonb,1,'Early structure prevents clutter.','original'),
('127.415.d.14.C',3,'A consistent naming convention includes the project number, document type, and:','["color", "nickname", "revision or date", "mood"]'::jsonb,2,'Names should carry key information.','original'),
('127.415.d.14.C',4,'File names like ''Plan_Sheet01_RevB'' follow a convention that makes it easy to identify the document and its:','["pet", "author''s lunch", "weather", "revision"]'::jsonb,3,'Revision letters track versions.','original'),
('127.415.d.14.D',3,'Using the same naming convention for every document on a project is important because it allows:','["anyone on the team to find the right file", "files to vanish", "files to hide", "random naming"]'::jsonb,0,'Uniformity helps everyone.','original'),
('127.415.d.14.D',4,'Maintaining a naming convention over the life of the project means applying it to:','["only the first file", "every new document", "only drawings", "only emails"]'::jsonb,1,'Consistency must be sustained.','original'),
('127.415.d.15.A',3,'A Gantt chart is a time management technique that displays tasks as horizontal bars over:','["a menu", "a score", "a calendar", "a map"]'::jsonb,2,'Gantt charts show schedules.','original'),
('127.415.d.15.A',4,'A critical path in a construction schedule is the sequence of tasks that determines the project''s:','["budget only", "color", "name", "minimum duration"]'::jsonb,3,'Delays on the critical path delay the project.','original'),
('127.415.d.15.B',3,'A written report to a client should be clear, organized, and free of:','["unexplained jargon", "figures", "headings", "dates"]'::jsonb,0,'Plain language aids communication.','original'),
('127.415.d.15.B',4,'When presenting orally to a city council, an engineer should use simple language and visuals to help the audience:','["ignore data", "understand the proposal", "leave early", "avoid questions"]'::jsonb,1,'Presentations should inform the audience.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
